const Calculator: React.FC<{ initialData?: BookingContextData | null }> = ({ initialData }) => {
  const [clientInfo, setClientInfo] = useState({ company: '', contact: '', email: '' });
  const [selectedProgram, setSelectedProgram] = useState<Program>(CATEGORIES[0].programs[0]); 
  const [durationIdx, setDurationIdx] = useState(0);
  const [pax, setPax] = useState(0);
  const [missionDate, setMissionDate] = useState(new Date().toISOString().split('T')[0]);
  const [venue, setVenue] = useState<keyof typeof VENUE_GROUNDS>('client');
  const [accommodation, setAccommodation] = useState<keyof typeof ACCOMMODATION_LEVELS>('none');
  const [transport, setTransport] = useState<keyof typeof FLEET_SOLUTIONS>('none');
  const [eventType, setEventType] = useState<keyof typeof EVENT_MULTIPLIERS>('corporate');
  const [selectedAddons, setSelectedAddons] = useState<string[]>([]);
  const [quoteId] = useState(`CCA-Q-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${Math.floor(1000 + Math.random() * 9000)}`);

  useEffect(() => {
    if (initialData) {
      if (initialData.program) setSelectedProgram(initialData.program);
      if (initialData.pax !== undefined) setPax(initialData.pax);
      if (initialData.durationIndex !== undefined) setDurationIdx(initialData.durationIndex);
    }
  }, [initialData]);

  const toggleAddon = (id: string) => {
    setSelectedAddons(prev => prev.includes(id) ? prev.filter(a => a !== id) : [...prev, id]);
  };

  const results = useMemo(() => {
    const variant = selectedProgram.durations ? selectedProgram.durations[durationIdx] : { price: selectedProgram.basePrice, days: 1, isGroup: false, label: '', threshold: 0, maxThreshold: 999, isPPAbove: false };
    const days = Math.ceil(variant.days || 1);

    let isFlat = variant.isGroup;
    let isPPAbove = variant.isPPAbove || false;

    if (pax <= 0 && !isFlat) {
      return { 
        subtotal: 0, deposit: 0, opsFee: 0, days, baseTotal: 0, 
        unitRate: variant.price, venueCost: 0, transportCost: 0, 
        accommodationCost: 0, addonsTotal: 0, vehicleCount: 0,
        marginError: null, selectedAddonsList: []
      };
    }

    let marginError: string | null = null;
    let baseTotal = 0;

    // Specific logic for Team Building (Corporates, NGOs, Chamas etc)
    if (selectedProgram.category === 'corporate' || selectedProgram.id.startsWith('tb_')) {
        const threshold = variant.threshold || 0;
        const maxThreshold = variant.maxThreshold || 999;

        if (pax < 40 && variant.isGroup) {
            marginError = "Group pricing variant selected but participant count is < 40.";
        } else if (pax >= 40 && pax <= 100 && !variant.isGroup) {
            marginError = "Consider switching to a 'Group Pricing' variant for counts between 40–100.";
        } else if (pax > 100 && selectedProgram.id === 'tb_corporate' && !isPPAbove) {
            marginError = "For groups > 100, select the 'Large Group (> 100 pax)' variant for per-person rates.";
        }

        if (isPPAbove) {
            baseTotal = pax * variant.price;
        } else if (isFlat) {
            baseTotal = variant.price;
        } else {
            baseTotal = pax * variant.price;
        }
    } 
    // First Aid & Fire Safety
    else if (selectedProgram.id === 'first_aid' || selectedProgram.id === 'fire_safety') {
        if (pax >= 30 && pax <= 60) {
            if (!isFlat) marginError = "Consider switching to 'Group Pricing' variant for groups over 30.";
            baseTotal = isFlat ? variant.price : pax * variant.price;
        } else if (pax > 60) {
            marginError = "Maximum 60 pax per session. Contact for larger group strategy.";
            baseTotal = pax * variant.price;
        } else {
            if (isFlat) marginError = "Group pricing requires minimum 30 participants.";
            baseTotal = pax * variant.price;
        }
    } 
    // Medic Standby (Base 55k with multipliers)
    else if (selectedProgram.id === 'medic_standby') {
        const baseCharge = 55000;
        const multiplier = EVENT_MULTIPLIERS[eventType].multiplier;
        baseTotal = variant.price + (baseCharge * (multiplier - 1));
    } 
    // Standard logic
    else {
        baseTotal = isFlat ? variant.price : pax * variant.price;
    }

    const venueCost = VENUE_GROUNDS[venue].price * days;
    const fleet = FLEET_SOLUTIONS[transport];
    let transportCost = 0;
    let vehicleCount = 0;
    if (fleet.capacity > 0) {
      vehicleCount = Math.ceil(pax / fleet.capacity);
      transportCost = vehicleCount * fleet.price * days;
    }

    const accommodationCost = ACCOMMODATION_LEVELS[accommodation].price * pax * Math.max(0, days - 0.5); 
    const addonsData = ADDONS.filter(a => selectedAddons.includes(a.id));
    const addonsTotal = addonsData.reduce((sum, a) => sum + (a.type === 'pp' ? a.price * pax : a.price), 0);

    const subtotalNoBuffer = baseTotal + venueCost + transportCost + accommodationCost + addonsTotal;
    const contingency = subtotalNoBuffer * 0.05; 
    const finalTotal = subtotalNoBuffer + contingency;

    return { 
      subtotal: finalTotal, deposit: finalTotal * 0.5, opsFee: contingency, days, baseTotal, 
      unitRate: variant.price, venueCost, transportCost, accommodationCost, addonsTotal,
      isFlat: isFlat && !isPPAbove, vehicleCount, marginError, selectedAddonsList: addonsData
    };
  }, [selectedProgram, durationIdx, pax, venue, accommodation, transport, eventType, selectedAddons]);

