                  <div className="space-y-3">
                     <label className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.4em] flex items-center gap-2"><Building2 size={12}/> Organization</label>
                     <input type="text" value={clientInfo.company} onChange={(e) => setClientInfo({...clientInfo, company: e.target.value})} placeholder="Group Name" className="w-full p-4 bg-gray-50 border-none text-sm font-bold" />
                  </div>
                  <div className="space-y-3">
                     <label className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.4em] flex items-center gap-2"><User size={12}/> Lead</label>
                     <input type="text" value={clientInfo.contact} onChange={(e) => setClientInfo({...clientInfo, contact: e.target.value})} placeholder="Contact Name" className="w-full p-4 bg-gray-50 border-none text-sm font-bold" />
                  </div>
                  <div className="space-y-3">
                     <label className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.4em] flex items-center gap-2"><Mail size={12}/> Email</label>
                     <input type="email" value={clientInfo.email} onChange={(e) => setClientInfo({...clientInfo, email: e.target.value})} placeholder="missions@cca.africa" className="w-full p-4 bg-gray-50 border-none text-sm font-bold" />
                  </div>
               </div>
            </section>

            <section className="space-y-10">
               <div className="flex items-center gap-4 border-b border-gray-100 pb-6">
                  <div className="w-10 h-10 bg-brand-green text-brand-gold flex items-center justify-center font-bold font-serif">02</div>
                  <h3 className="text-xl font-serif font-bold text-brand-green uppercase">Configuration</h3>
               </div>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
