const Calculator: React.FC<{ initialData?: BookingContextData | null }> = ({ initialData }) => {
  const [clientInfo, setClientInfo] = useState({ company: '', contact: '', email: '' });
  const [selectedProgram, setSelectedProgram] = useState<Program>(CATEGORIES[0].programs[0]); 
  const [durationIdx, setDurationIdx] = useState(0);
  const [pax, setPax] = useState(0);
  const [missionDate, setMissionDate] = useState(new Date().toISOString().split('T')[0]);

  const [venueType, setVenueType] = useState<keyof typeof VENUE_TYPES>('public');
  const [venueAddons, setVenueAddons] = useState<string[]>([]);

  const [accommodation, setAccommodation] = useState<keyof typeof ACCOMMODATION_LEVELS>('none');
  const [accommAddons, setAccommAddons] = useState<string[]>([]);

  const [fleetType, setFleetType] = useState<keyof typeof FLEET_SOLUTIONS>('none');
  const [fleetAddons, setFleetAddons] = useState<string[]>([]);

  const [selectedMeals, setSelectedMeals] = useState<string[]>([]);
  const [eventType, setEventType] = useState<keyof typeof EVENT_TYPE_RISK>('corporate');
  const [safetyAddons, setSafetyAddons] = useState<string[]>([]);

  const [quoteId] = useState(`CCA-Q-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${Math.floor(1000 + Math.random() * 9000)}`);

  useEffect(() => {
    if (initialData) {
      if (initialData.program) setSelectedProgram(initialData.program);
      if (initialData.pax !== undefined) setPax(initialData.pax);
      if (initialData.durationIndex !== undefined) setDurationIdx(initialData.durationIndex);
    }
  }, [initialData]);

  const results = useMemo(() => {
    const variant = selectedProgram.durations ? selectedProgram.durations[durationIdx] : { price: selectedProgram.basePrice, days: 1, isGroup: false, threshold: 0, maxThreshold: 999, isPPAbove: false };
    const days = Math.ceil(variant.days || 1);
    const nights = Math.max(0, days - 1);

    let isFlat = variant.isGroup;
    let isPPAbove = variant.isPPAbove || false;
    let marginError: string | null = null;

    // 1. Mission Base Calculation
    let missionBase = 0;
    if (pax > 0) {
        if (isPPAbove) missionBase = pax * variant.price;
        else if (isFlat) missionBase = variant.price;
        else missionBase = pax * variant.price;
    }

    // 2. Risk Management (Safety Pillar)
    const riskMultiplier = EVENT_TYPE_RISK[eventType].multiplier;
    const riskBase = 55000;
    const safetyBaseCharge = riskBase * riskMultiplier;
    const safetyAddonsTotal = safetyAddons.reduce((sum, id) => {
        const item = SAFETY_ADDONS.find(a => a.id === id);
        return sum + (item?.price || 0);
    }, 0);

    // 3. Venue & Logistics
    const venueBase = VENUE_TYPES[venueType].price * days;
    const venueAddonsTotal = venueAddons.reduce((sum, id) => {
        const item = VENUE_ADDONS.find(a => a.id === id);
        if (!item) return sum;
        return sum + (item.type === 'pp' ? item.price * pax : item.price) * days;
    }, 0);

    // 4. Accommodation
    const accommBase = ACCOMMODATION_LEVELS[accommodation].price * pax * nights;
    const accommAddonsTotal = accommAddons.reduce((sum, id) => {
        const item = ACCOMM_ADDONS.find(a => a.id === id);
        return sum + (item?.price || 0) * nights;
    }, 0);

    // 5. Meals
    const mealsTotal = selectedMeals.reduce((sum, id) => {
        const meal = MEALS.find(m => m.id === id);
        return sum + (meal?.price || 0) * pax * days;
    }, 0);

    // 6. Transport
    const fleet = FLEET_SOLUTIONS[fleetType];
    let transportBase = 0;
    let vehicleCount = 0;
    if (fleet.capacity > 0) {
        vehicleCount = Math.ceil(pax / fleet.capacity);
        transportBase = vehicleCount * fleet.price * days;
    }
    const fleetAddonsTotal = fleetAddons.reduce((sum, id) => {
        const item = FLEET_ADDONS.find(a => a.id === id);
        if (!item) return sum;
        if (item.type === 'percent') return sum + (transportBase * item.val!);
        return sum + item.price * vehicleCount;
    }, 0);

    const subtotal = missionBase + safetyBaseCharge + safetyAddonsTotal + venueBase + venueAddonsTotal + accommBase + accommAddonsTotal + mealsTotal + transportBase + fleetAddonsTotal;
    const contingency = subtotal * 0.05; // 5% ops buffer
    const finalTotal = subtotal + contingency;

    // Threshold Checks
    if (selectedProgram.id === 'tb_corporate') {
        if (pax >= 40 && pax <= 100 && !isFlat) marginError = "Optimize: Switch to Group Tier for 40–100 pax.";
        if (pax > 100 && !isPPAbove) marginError = "Optimize: Switch to Large Group PP variant for > 100 pax.";
    }

    return { 
        subtotal: finalTotal, 
        deposit: finalTotal * 0.5, 
        opsFee: contingency,
        missionBase,
        safetyBase: safetyBaseCharge + safetyAddonsTotal,
        logisticsBase: venueBase + venueAddonsTotal + accommBase + accommAddonsTotal + mealsTotal + transportBase + fleetAddonsTotal,
        marginError,
        days,
        nights
    };
  }, [selectedProgram, durationIdx, pax, venueType, venueAddons, accommodation, accommAddons, selectedMeals, fleetType, fleetAddons, eventType, safetyAddons]);

  const formatKES = (n: number) => `KES ${n.toLocaleString()}`;

  const handleWhatsApp = () => {
    const formattedDate = new Date(missionDate).toLocaleDateString('en-KE', { dateStyle: 'long' });
    const message = `*CROSS CONNECT AFRICA*
*MISSION QUOTE REQUEST*
ID: ${quoteId}
MISSION: ${selectedProgram.title}
PAX: ${pax}
RISK FACTOR: ${EVENT_TYPE_RISK[eventType].label}
DEPLOYMENT: ${formattedDate}
INVESTMENT: ${formatKES(results.subtotal)}
COMMITMENT: ${formatKES(results.deposit)}`;
    window.open(`https://wa.me/254710974670?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen bg-brand-cream pt-40 pb-32 px-6 md:px-12">
      <div className="max-w-[1800px] mx-auto grid lg:grid-cols-12 gap-12 items-stretch">

        {/* INPUTS COLUMN */}
        <div className="lg:col-span-8 space-y-10 print:hidden">
          <div className="bg-white p-10 shadow-2xl border border-brand-green/5 space-y-16">

            {/* 01: IDENTITY */}
            <section className="space-y-8">
               <div className="flex items-center gap-4 border-b border-gray-100 pb-4">
                  <div className="w-10 h-10 bg-brand-green text-brand-gold flex items-center justify-center font-bold font-serif">01</div>
                  <h3 className="text-xl font-serif font-bold text-brand-green uppercase">Mission Identity</h3>
               </div>
               <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="space-y-2">
                     <label className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.4em]">Organization</label>
                     <input type="text" value={clientInfo.company} onChange={(e) => setClientInfo({...clientInfo, company: e.target.value})} placeholder="Group Name" className="w-full p-4 bg-gray-50 border-none text-sm font-bold" />
                  </div>
                  <div className="space-y-2">
                     <label className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.4em]">Lead Contact</label>
                     <input type="text" value={clientInfo.contact} onChange={(e) => setClientInfo({...clientInfo, contact: e.target.value})} placeholder="Full Name" className="w-full p-4 bg-gray-50 border-none text-sm font-bold" />
                  </div>
                  <div className="space-y-2">
                     <label className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.4em]">Email</label>
                     <input type="email" value={clientInfo.email} onChange={(e) => setClientInfo({...clientInfo, email: e.target.value})} placeholder="missions@cca.africa" className="w-full p-4 bg-gray-50 border-none text-sm font-bold" />
                  </div>
               </div>
            </section>

            {/* 02: CONFIGURATION */}
            <section className="space-y-10">
               <div className="flex items-center gap-4 border-b border-gray-100 pb-4">
                  <div className="w-10 h-10 bg-brand-green text-brand-gold flex items-center justify-center font-bold font-serif">02</div>
                  <h3 className="text-xl font-serif font-bold text-brand-green uppercase">Mission Core</h3>
               </div>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  <div className="space-y-6">
                     <div className="space-y-3">
                        <label className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.4em]">Service Pillar</label>
                        <select 
                           value={selectedProgram.id} 
                           onChange={(e) => {
                              const prog = CATEGORIES.flatMap(c => c.programs).find(p => p.id === e.target.value);
                              if (prog) { setSelectedProgram(prog); setDurationIdx(0); }
                           }}
                           className="w-full p-5 bg-gray-50 border-none text-[11px] font-bold uppercase tracking-widest"
                        >
                           {CATEGORIES.map(cat => (
                              <optgroup key={cat.id} label={cat.title}>
                                 {cat.programs.map(p => <option key={p.id} value={p.id}>{p.title}</option>)}
                              </optgroup>
                           ))}
                        </select>
                     </div>
                     <div className="space-y-3">
                        <label className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.4em]">Variant / Duration</label>
