                    </div>
                    <span className="text-sm font-bold text-brand-green">{formatKES(results.safetyBase)}</span>
                 </div>

                 <div className="flex justify-between items-end border-b border-gray-50 pb-4">
                    <div className="space-y-1">
                       <span className="text-[8px] font-bold text-gray-400 uppercase tracking-widest block">03 Field Logistics</span>
                       <span className="text-[11px] font-serif font-bold italic text-brand-green">Venue, Transport, Hospitality</span>
                    </div>
                    <span className="text-sm font-bold text-brand-green">{formatKES(results.logisticsBase)}</span>
                 </div>

                 <section className="bg-brand-green text-white p-8 mt-12 space-y-4 shadow-xl">
                    <span className="text-brand-gold text-[10px] font-bold uppercase tracking-[0.5em] block">Total Investment</span>
                    <div className="text-5xl font-serif font-bold text-brand-gold tracking-tighter leading-none">{formatKES(results.subtotal)}</div>
                    <div className="pt-4 border-t border-white/10 flex justify-between items-center">
                       <span className="text-[9px] uppercase font-bold tracking-[0.3em] opacity-60">50% Commitment</span>
                       <span className="text-xl font-serif font-bold text-brand-gold">{formatKES(results.deposit)}</span>
                    </div>
                 </section>

                 <div className="pt-8 flex flex-col gap-4 print:hidden">
                    <button onClick={handleWhatsApp} className="w-full py-5 bg-[#25D366] text-white font-bold text-[10px] uppercase tracking-[0.5em] shadow-lg flex items-center justify-center gap-3">
                       <MessageCircle size={20} /> Request Proposal
                    </button>
                    <button onClick={() => window.print()} className="w-full py-4 border border-brand-green text-brand-green font-bold text-[9px] uppercase tracking-widest">Print Strategy Log</button>
                 </div>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

