    return selectedProgram.durations?.[durationIdx]?.price || selectedProgram.basePrice;
  }, [selectedProgram, durationIdx]);

  const isGroupRate = useMemo(() => {
    return selectedProgram.priceType === 'flat_rate' || selectedProgram.durations?.[durationIdx]?.isGroup || false;
  }, [selectedProgram, durationIdx]);

  const isPPAboveRate = useMemo(() => {
    return selectedProgram.durations?.[durationIdx]?.isPPAbove || false;
  }, [selectedProgram, durationIdx]);

  const estimatedInvestment = useMemo(() => {
    if (formData.groupSize <= 0) {
       return (isGroupRate && !isPPAboveRate) ? currentRate : 0;
    }
    if (isGroupRate && !isPPAboveRate) return currentRate;
    return currentRate * formData.groupSize;
  }, [formData.groupSize, isGroupRate, isPPAboveRate, currentRate]);

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setItinerary(null);
    setOriginalItinerary(null);
    try {
