      items: itinerary.items.map(item => item.id === id ? { ...item, [field]: value } : item)
    });
  };

  const restoreItineraryItem = (id: string) => {
    if (!originalItinerary || !itinerary) return;
    const originalItem = originalItinerary.items.find(item => item.id === id);
    if (originalItem) {
