const Calculator: React.FC<{ initialData?: BookingContextData | null }> = ({ initialData }) => {
  const [clientInfo, setClientInfo] = useState({ company: '', contact: '', email: '' });
  const [selectedProgram, setSelectedProgram] = useState<Program | null>(initialData?.program || null); 
  const [durationIdx, setDurationIdx] = useState(initialData?.durationIndex || 0);
  const [pax, setPax] = useState(initialData?.pax || 0);
  const [missionDate, setMissionDate] = useState(new Date().toISOString().split('T')[0]);

  const [venueType, setVenueType] = useState<keyof typeof VENUE_TYPES>('public');
  const [venueAddons, setVenueAddons] = useState<string[]>([]);

  const [accommodation, setAccommodation] = useState<keyof typeof ACCOMMODATION_LEVELS>('none');
  const [accommAddons, setAccommAddons] = useState<string[]>([]);

  const [fleetType, setFleetType] = useState<keyof typeof FLEET_SOLUTIONS>('none');
  const [fleetAddons, setFleetAddons] = useState<string[]>([]);

  const [selectedMeals, setSelectedMeals] = useState<string[]>([]);

  const [quoteId] = useState(`CCA-Q-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${Math.floor(1000 + Math.random() * 9000)}`);

  const results = useMemo(() => {
    if (!selectedProgram || pax <= 0) {
      return { subtotal: 0, deposit: 0, missionBase: 0, logisticsBase: 0, days: 0, nights: 0 };
    }

    const variant = selectedProgram.durations ? selectedProgram.durations[durationIdx] : { price: selectedProgram.basePrice, days: 1, isGroup: false };
    const days = Math.ceil(variant.days || 1);
    const nights = Math.max(0, days - 1);

    // 1. Mission Base Calculation
    let missionBase = 0;
    missionBase = variant.isGroup ? variant.price : (variant.price * pax);

    // 2. Venue & Logistics
    const venueBase = VENUE_TYPES[venueType].price * days;
    const venueAddonsTotal = venueAddons.reduce((sum, id) => {
        const item = VENUE_ADDONS.find(a => a.id === id);
        if (!item) return sum;
        return sum + (item.type === 'pp' ? item.price * pax : item.price) * days;
    }, 0);

    // 3. Accommodation
    const accommBase = ACCOMMODATION_LEVELS[accommodation].price * pax * nights;
    const accommAddonsTotal = accommAddons.reduce((sum, id) => {
        const item = ACCOMM_ADDONS.find(a => a.id === id);
        return sum + (item?.price || 0) * nights;
    }, 0);

    // 4. Meals
    const mealsTotal = selectedMeals.reduce((sum, id) => {
        const meal = MEALS.find(m => m.id === id);
        return sum + (meal?.price || 0) * pax * days;
    }, 0);

    // 5. Transport
    const fleet = FLEET_SOLUTIONS[fleetType];
    let transportBase = 0;
    let vehicleCount = 0;
    if (fleet.capacity > 0) {
        vehicleCount = Math.ceil(pax / fleet.capacity);
        transportBase = vehicleCount * fleet.price * days;
    }
    const fleetAddonsTotal = fleetAddons.reduce((sum, id) => {
        const item = FLEET_ADDONS.find(a => a.id === id);
        if (!item) return sum;
        if (item.type === 'percent') return sum + (transportBase * item.val!);
        return sum + item.price * (vehicleCount || 1);
    }, 0);

