                        {ACCOMM_ADDONS.map(a => (
                           <button key={a.id} onClick={() => setAccommAddons(prev => prev.includes(a.id) ? prev.filter(x => x !== a.id) : [...prev, a.id])} className={`p-4 border text-left text-[10px] font-bold uppercase flex justify-between items-center ${accommAddons.includes(a.id) ? 'bg-brand-sand border-brand-green' : 'bg-gray-50 border-transparent'}`}>
