                              <div className="text-[11px] font-bold mt-1">{formatKES(m.price)} pp</div>
                           </button>
                        ))}
                     </div>
                  </div>
               </div>
            </section>
          </div>
        </div>

        {/* QUOTE STUB COLUMN */}
        <div className="lg:col-span-4">
           <div id="quote-doc" className="bg-white p-12 shadow-2xl paper-texture sticky top-32 border border-gray-100">
              <header className="border-b-[6px] border-brand-green pb-8 mb-10">
                 <div className="flex justify-between items-start mb-6">
                    <Logo className="w-14 h-14" />
                    <div className="text-right">
                       <div className="text-[8px] font-bold uppercase text-gray-400 tracking-widest">{quoteId}</div>
                       <div className="text-[9px] font-bold uppercase text-brand-gold tracking-[0.4em]">Strategy Record</div>
                    </div>
                 </div>
                 <h2 className="text-3xl font-serif font-bold text-brand-green italic truncate leading-none mb-2">{clientInfo.company || 'Mission Partner'}</h2>
                 <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{new Date(missionDate).toLocaleDateString('en-KE')} — {pax} PAX</p>
              </header>

              <div className="space-y-6">
                 {results.missionBase > 0 && (
                   <div className="flex justify-between items-end border-b border-gray-50 pb-4 animate-reveal">
                      <div className="space-y-1">
                         <span className="text-[8px] font-bold text-gray-400 uppercase tracking-widest block">01 Mission Core</span>
                         <span className="text-[11px] font-serif font-bold italic text-brand-green">{selectedProgram?.title || 'No Selection'}</span>
                      </div>
                      <span className="text-sm font-bold text-brand-green">{formatKES(results.missionBase)}</span>
                   </div>
                 )}

                 {results.logisticsBase > 0 && (
                   <div className="flex justify-between items-end border-b border-gray-50 pb-4 animate-reveal">
                      <div className="space-y-1">
                         <span className="text-[8px] font-bold text-gray-400 uppercase tracking-widest block">02 Field Logistics</span>
                         <span className="text-[11px] font-serif font-bold italic text-brand-green">Venue, Transport, Hospitality</span>
                      </div>
                      <span className="text-sm font-bold text-brand-green">{formatKES(results.logisticsBase)}</span>
                   </div>
                 )}

                 <section className="bg-brand-green text-white p-8 mt-12 space-y-4 shadow-xl">
                    <span className="text-brand-gold text-[10px] font-bold uppercase tracking-[0.5em] block">Total Investment</span>
                    <div className="text-5xl font-serif font-bold text-brand-gold tracking-tighter leading-none">{formatKES(results.subtotal)}</div>
                    <div className="pt-4 border-t border-white/10 flex justify-between items-center">
                       <span className="text-[9px] uppercase font-bold tracking-[0.3em] opacity-60">50% Commitment</span>
                       <span className="text-xl font-serif font-bold text-brand-gold">{formatKES(results.deposit)}</span>
                    </div>
                 </section>

                 <div className="pt-8 flex flex-col gap-4 print:hidden">
                    <button 
                      onClick={handleWhatsApp} 
                      disabled={!selectedProgram || pax <= 0}
                      className="w-full py-5 bg-[#25D366] text-white font-bold text-[10px] uppercase tracking-[0.5em] shadow-lg flex items-center justify-center gap-3 disabled:opacity-50"
                    >
                       <MessageCircle size={20} /> Request Proposal
                    </button>
                    <button onClick={() => window.print()} className="w-full py-4 border border-brand-green text-brand-green font-bold text-[9px] uppercase tracking-widest">Print Strategy Log</button>
                 </div>

                 {(!selectedProgram || pax === 0) && (
                   <div className="bg-brand-sand p-4 border-l-4 border-brand-gold flex gap-3 animate-pulse">
                      <AlertTriangle className="text-brand-gold shrink-0" size={16} />
                      <p className="text-[9px] font-bold text-brand-green uppercase leading-relaxed tracking-tight">Mission quote starts at zero. Select a program and enter participant count to initiate strategy calculation.</p>
                   </div>
                 )}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

