                     </div>
                     <div className="space-y-3">
                        <label className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.4em]">Participants (Pax)</label>
                        <input type="number" value={pax} onChange={(e) => setPax(Math.max(0, parseInt(e.target.value) || 0))} className="w-full p-3.5 bg-gray-50 border-none font-serif font-bold text-2xl" />
                     </div>
                  </div>
               </div>

               {selectedProgram?.id === 'medic_standby' && (
                   <div className="bg-brand-sand/50 p-6 space-y-4 animate-reveal">
                      <label className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.4em] flex items-center gap-2"><ShieldAlert size={14}/> Event Risk Adjustment</label>
                      <select value={eventType} onChange={(e) => setEventType(e.target.value as any)} className="w-full p-4 bg-white border-none text-xs font-bold uppercase">
                        {Object.values(EVENT_TYPE_RISK).map(et => <option key={et.id} value={et.id}>{et.label} (+{Math.round((et.multiplier - 1) * 100)}%)</option>)}
                      </select>
                   </div>
               )}
            </section>

            {/* 03: LOGISTICS */}
            <section className="space-y-10">
               <div className="flex items-center gap-4 border-b border-gray-100 pb-4">
                  <div className="w-10 h-10 bg-brand-green text-brand-gold flex items-center justify-center font-bold font-serif">03</div>
